def es_palindromo(texto):
    s = [c.lower() for c in texto if c.isalnum()]
    return s == s[::-1]

def fizzbuzz(n):
    out = []
    for i in range(1, n + 1):
        s = ('Fizz' if i % 3 == 0 else '') + ('Buzz' if i % 5 == 0 else '')
        out.append(s or str(i))
    return out

def contar_palabras(texto):
    d = {}
    for w in texto.lower().split():
        d[w] = d.get(w, 0) + 1
    return d

def fibonacci(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def fusionar_intervalos(intervalos):
    out = []
    for a, b in sorted(intervalos):
        if out and a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return out

def romano_a_entero(s):
    v = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    t = 0
    for i, c in enumerate(s):
        if i + 1 < len(s) and v[c] < v[s[i + 1]]:
            t -= v[c]
        else:
            t += v[c]
    return t

def balanceado(texto):
    pares = {')': '(', ']': '[', '}': '{'}
    pila = []
    for c in texto:
        if c in '([{':
            pila.append(c)
        elif c in pares:
            if not pila or pila.pop() != pares[c]:
                return False
    return not pila
